const WD=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const MO=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
let state={tasks:[],rules:[],settings:[]};
let revs=new Map();
let today='';
const $=(id)=>document.getElementById(id);

function pad(n){return String(n).padStart(2,'0');}
function toDays(s){
  const [y0,m,d]=s.split('-').map(Number);
  const y=m<=2?y0-1:y0;
  const era=Math.floor(y/400);
  const yoe=y-era*400;
  const doy=Math.floor((153*(m+(m>2?-3:9))+2)/5)+d-1;
  const doe=yoe*365+Math.floor(yoe/4)-Math.floor(yoe/100)+doy;
  return era*146097+doe-719468;
}
function fromDays(n){
  const z=n+719468;
  const era=Math.floor(z/146097);
  const doe=z-era*146097;
  const yoe=Math.floor((doe-Math.floor(doe/1460)+Math.floor(doe/36524)-Math.floor(doe/146096))/365);
  const doy=doe-(365*yoe+Math.floor(yoe/4)-Math.floor(yoe/100));
  const mp=Math.floor((5*doy+2)/153);
  const d=doy-Math.floor((153*mp+2)/5)+1;
  const m=mp<10?mp+3:mp-9;
  const y=yoe+era*400+(m<=2?1:0);
  return y+'-'+pad(m)+'-'+pad(d);
}
function weekday(n){return ((n+4)%7+7)%7;}
function pretty(s){
  const n=toDays(s);
  const [y,m,d]=s.split('-').map(Number);
  return WD[weekday(n)]+', '+d+' '+MO[m-1]+' '+y;
}
function examDate(){
  const [s]=state.settings;
  if(s&&s.exam){return s.exam;}
  return fromDays(toDays(today)+14);
}
function blockedSet(extra){
  const set=new Set();
  for(const r of state.rules){set.add(r.weekday);}
  if(extra!==undefined){set.add(extra);}
  return set;
}
function candidateDays(blocked){
  const start=toDays(today);
  const end=Math.max(toDays(examDate())-1,start+6);
  const out=[];
  for(let n=start;n<=end;n++){
    if(!blocked.has(weekday(n))){out.push(fromDays(n));}
  }
  return out;
}
function loadMap(skip){
  const m=new Map();
  for(const t of state.tasks){
    for(const s of t.sessions){
      if(skip&&skip(t,s)){continue;}
      m.set(s.date,(m.get(s.date)||0)+1);
    }
  }
  return m;
}
function place(days,load,used){
  let best=null;let bestScore=Infinity;
  for(const day of days){
    const score=(used.has(day)?100:0)+(load.get(day)||0);
    if(score<bestScore){bestScore=score;best=day;}
  }
  if(best!==null){
    load.set(best,(load.get(best)||0)+1);
    used.add(best);
  }
  return best;
}

function say(text,bad){
  const s=$('status');
  s.textContent=text;
  s.className='status'+(bad?' bad':'');
}
async function load(){
  const res=await tessera.call('data.read',{});
  const d=res.data;
  state={tasks:d.tasks||[],rules:d.rules||[],settings:d.settings||[]};
  revs=new Map();
  for(const [c,o] of Object.entries(res.revisions)){
    for(const [id,n] of Object.entries(o)){revs.set(c+'/'+id,n);}
  }
  render();
}
function rv(c,id){return revs.get(c+'/'+id)||1;}
async function patch(ops){
  await tessera.call('data.patch',{operations:ops});
  await load();
}

function render(){
  const exam=examDate();
  $('exam').value=exam;
  const left=toDays(exam)-toDays(today);
  $('left').textContent=left>=0?(left===1?'1 day left':left+' days left'):'The exam date has passed.';

  const rl=$('rules');rl.textContent='';
  const sorted=state.rules.slice().sort((a,b)=>a.weekday-b.weekday);
  if(sorted.length===0){
    const li=document.createElement('li');
    li.textContent='No rules yet: sessions can fall on any day.';
    rl.appendChild(li);
  }
  for(const r of sorted){
    const li=document.createElement('li');
    li.setAttribute('data-hook','rule');
    const sp=document.createElement('span');
    sp.textContent='No sessions on '+WD[r.weekday];
    const b=document.createElement('button');
    b.type='button';
    b.setAttribute('data-hook','rule-remove');
    b.textContent='Remove rule';
    b.setAttribute('aria-label','Remove rule: no sessions on '+WD[r.weekday]);
    b.addEventListener('click',()=>removeRule(r.id));
    li.appendChild(sp);li.appendChild(b);
    rl.appendChild(li);
  }

  const all=[];
  for(const t of state.tasks){
    t.sessions.forEach((s,i)=>all.push({task:t,i:i,date:s.date,done:s.done}));
  }
  all.sort((a,b)=>a.date<b.date?-1:a.date>b.date?1:a.task.name.localeCompare(b.task.name));
  const plan=$('plan');plan.textContent='';
  if(all.length===0){
    const p=document.createElement('p');
    p.className='muted';
    p.textContent='No sessions yet. Add a topic above and it will be scheduled for you.';
    plan.appendChild(p);
  }
  let curDate=null;let ul=null;
  for(const e of all){
    if(e.date!==curDate){
      curDate=e.date;
      const h=document.createElement('h3');
      h.textContent=pretty(e.date)+' (evening)';
      plan.appendChild(h);
      ul=document.createElement('ul');ul.className='plain';
      plan.appendChild(ul);
    }
    const li=document.createElement('li');
    li.className='session'+(e.done?' done':'');
    li.setAttribute('data-hook','session');
    const lab=document.createElement('label');
    const cb=document.createElement('input');
    cb.type='checkbox';cb.checked=!!e.done;
    cb.addEventListener('change',()=>toggle(e.task.id,e.i,cb.checked));
    const tn=document.createElement('span');
    tn.className='tn';
    tn.setAttribute('data-hook','session-task');
    tn.textContent=e.task.name;
    lab.appendChild(cb);lab.appendChild(tn);
    const tm=document.createElement('time');
    tm.setAttribute('datetime',e.date);
    tm.className='muted';
    const [yy,mm,dd]=e.date.split('-').map(Number);
    tm.textContent=dd+' '+MO[mm-1];
    li.appendChild(lab);li.appendChild(tm);
    ul.appendChild(li);
  }

  const tl=$('topics');tl.textContent='';
  if(state.tasks.length===0){
    const li=document.createElement('li');
    li.textContent='No topics yet.';
    tl.appendChild(li);
  }
  for(const t of state.tasks){
    const li=document.createElement('li');
    const sp=document.createElement('span');
    const dn=t.sessions.filter((s)=>s.done).length;
    sp.textContent=t.name+' — '+dn+' of '+t.sessions.length+' sessions done';
    const b=document.createElement('button');
    b.type='button';
    b.textContent='Remove topic';
    b.setAttribute('aria-label','Remove topic '+t.name);
    b.addEventListener('click',()=>removeTask(t.id,t.name));
    li.appendChild(sp);li.appendChild(b);
    tl.appendChild(li);
  }
}

async function addTask(){
  const input=$('tname');
  const name=input.value.trim();
  $('terr').textContent='';
  if(!name){$('terr').textContent='Type the topic’s name first.';input.focus();return;}
  let n=parseInt($('tcount').value,10);
  if(!(n>=1)){n=1;}
  if(n>7){n=7;}
  const days=candidateDays(blockedSet());
  if(days.length===0){$('terr').textContent='Every weekday is ruled out, so there is no day to study. Remove a rule first.';return;}
  const ld=loadMap();
  const used=new Set();
  const sessions=[];
  for(let i=0;i<n;i++){
    const day=place(days,ld,used);
    sessions.push({date:day,done:false});
  }
  sessions.sort((a,b)=>a.date<b.date?-1:1);
  try{
    await patch([{op:'add',collection:'tasks',record:{name:name,sessions:sessions}}]);
    input.value='';
    say('Added “'+name+'” with '+n+(n===1?' session.':' sessions.'));
    input.focus();
  }catch(err){
    say('Could not add the topic. Nothing was changed; please try again.',true);
  }
}
async function toggle(id,i,val){
  const t=state.tasks.find((x)=>x.id===id);
  if(!t){return;}
  const sessions=t.sessions.map((s,k)=>k===i?{date:s.date,done:val}:s);
  try{
    await patch([{op:'replace',collection:'tasks',id:id,revisionCount:rv('tasks',id),fields:{sessions:sessions}}]);
  }catch(err){
    say('Could not update that session. Please try again.',true);
    await load();
  }
}
async function removeTask(id,name){
  try{
    await patch([{op:'remove',collection:'tasks',id:id,revisionCount:rv('tasks',id)}]);
    say('Removed “'+name+'” and its sessions.');
  }catch(err){
    say('Could not remove the topic. Please try again.',true);
  }
}
async function addRule(){
  $('rerr').textContent='';
  const day=parseInt($('rday').value,10);
  if(state.rules.some((r)=>r.weekday===day)){
    $('rerr').textContent='There is already a rule for '+WD[day]+'.';return;
  }
  const blocked=blockedSet(day);
  if(blocked.size>=7){
    $('rerr').textContent='That would rule out every day of the week. Keep at least one study day.';return;
  }
  const days=candidateDays(blocked);
  const isMoved=(s)=>s.date>=today&&weekday(toDays(s.date))===day;
  const ld=loadMap((t,s)=>isMoved(s));
  const ops=[{op:'add',collection:'rules',record:{weekday:day}}];
  let moved=0;
  for(const t of state.tasks){
    if(!t.sessions.some(isMoved)){continue;}
    const used=new Set();
    for(const s of t.sessions){if(!isMoved(s)){used.add(s.date);}}
    const sessions=t.sessions.map((s)=>{
      if(!isMoved(s)){return s;}
      const nd=place(days,ld,used);
      moved++;
      return {date:nd===null?s.date:nd,done:s.done};
    });
    sessions.sort((a,b)=>a.date<b.date?-1:a.date>b.date?1:0);
    ops.push({op:'replace',collection:'tasks',id:t.id,revisionCount:rv('tasks',t.id),fields:{sessions:sessions}});
  }
  try{
    await patch(ops);
    say('Rule added: no sessions on '+WD[day]+'. '+moved+(moved===1?' session moved.':' sessions moved.'));
  }catch(err){
    say('Could not add the rule. Nothing was changed; please try again.',true);
  }
}
async function removeRule(id){
  try{
    await patch([{op:'remove',collection:'rules',id:id,revisionCount:rv('rules',id)}]);
    say('Rule removed. Planned sessions stay where they are.');
  }catch(err){
    say('Could not remove the rule. Please try again.',true);
  }
}
async function saveExam(){
  const v=$('exam').value;
  if(!v){return;}
  const [s]=state.settings;
  try{
    if(s){await patch([{op:'replace',collection:'settings',id:s.id,revisionCount:rv('settings',s.id),fields:{exam:v}}]);}
    else{await patch([{op:'add',collection:'settings',record:{exam:v}}]);}
    say('Exam date saved.');
  }catch(err){
    say('Could not save the exam date. Please try again.',true);
  }
}

for(let i=0;i<7;i++){
  const o=document.createElement('option');
  o.value=String(i);o.textContent=WD[i];
  $('rday').appendChild(o);
}
$('rday').value='5';
$('addtask').addEventListener('click',addTask);
$('addrule').addEventListener('click',addRule);
$('exam').addEventListener('change',saveExam);
$('tname').addEventListener('keydown',(e)=>{if(e.key==='Enter'){e.preventDefault();addTask();}});

(async()=>{
  try{
    const c=await tessera.call('clock.now',{});
    today=c.date;
    await load();
  }catch(err){
    say('Could not open your plan. Please reopen the tool.',true);
  }
})();

